package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.SubLine;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class SubLine_intersection_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_IncludeEndpoints_BothInside() {
        // Line 1: x-axis from -10 to 10
        SubLine sub1 = new SubLine(new Vector3D(-10, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 10
        SubLine sub2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 10, 0));

        Vector3D result = sub1.intersection(sub2, true);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndpoints_OneAtBoundary() {
        // Line 1: x-axis from 0 to 10
        SubLine sub1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 0 (intersects sub1 at origin, which is endpoint)
        SubLine sub2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 0, 0));

        Vector3D result = sub1.intersection(sub2, true);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndpoints_OneOutside() {
        // Line 1: x-axis from 0 to 10
        SubLine sub1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from 1 to 10 (does not touch sub1)
        SubLine sub2 = new SubLine(new Vector3D(0, 1, 0), new Vector3D(0, 10, 0));

        Vector3D result = sub1.intersection(sub2, true);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndpoints_BothInside() {
        // Line 1: x-axis from -10 to 10
        SubLine sub1 = new SubLine(new Vector3D(-10, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 10
        SubLine sub2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 10, 0));

        Vector3D result = sub1.intersection(sub2, false);
        assertVectorEquals(new Vector3D(0, 0, 0), result);
    }

    @Test
    public void testIntersection_ExcludeEndpoints_OneAtBoundary() {
        // Line 1: x-axis from 0 to 10
        SubLine sub1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from -10 to 0
        SubLine sub2 = new SubLine(new Vector3D(0, -10, 0), new Vector3D(0, 0, 0));

        // Since loc1 or loc2 will be BOUNDARY (not INSIDE), it should return null
        Vector3D result = sub1.intersection(sub2, false);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndpoints_BothOutside() {
        // Line 1: x-axis from 5 to 10
        SubLine sub1 = new SubLine(new Vector3D(5, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from 5 to 10
        SubLine sub2 = new SubLine(new Vector3D(0, 5, 0), new Vector3D(0, 10, 0));

        // The infinite lines intersect at (0,0,0), which is outside both sub-lines
        Vector3D result = sub1.intersection(sub2, false);
        assertNull(result);
    }

    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        if (expected == null || actual == null) {
            assertEquals(expected, actual);
            return;
        }
        assertEquals("X coordinate mismatch", expected.getX(), actual.getX(), EPSILON);
        assertEquals("Y coordinate mismatch", expected.getY(), actual.getY(), EPSILON);
        assertEquals("Z coordinate mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}
